    try:
        arr_typed = arr.astype(dtype)
        for axis in [None, 0]:
            try:
                result_nanstd = nanops.nanstd(arr_typed, mask=mask, skipna=False, axis=axis)
                probe(f"nanops.nanstd / nanops.nansem(np.array([[1, 1], [5, 2], [3, 0]], dtype={dtype_name}), mask=np.array([[False, False], [True, False], [False, False]]), skipna=False, axis={axis})", result_nanstd)
            except Exception as e:
                probe_exception(f"nanops.nanstd / nanops.nansem(np.array([[1, 1], [5, 2], [3, 0]], dtype={dtype_name}), mask=np.array([[False, False], [True, False], [False, False]]), skipna=False, axis={axis})", e)

